<?php
/* Puts the operations manual into the Library (tt_library/3_Docs_Playbooks), which sits
   outside the web root. No patching, no overwriting of anything else. */
@ini_set('display_errors','0');
$REPORT = __DIR__ . '/lib-report.txt'; $log = [];
function out($s) { global $log, $REPORT; $log[] = $s; @file_put_contents($REPORT, implode("\n",$log)."\n"); echo $s . "\n"; }
if (($_GET['go'] ?? '') !== '900a07c230856b47') { http_response_code(404); exit; }
header('Content-Type: text/plain; charset=utf-8');
$root = preg_match('~/_inst~', __DIR__) ? dirname(__DIR__) : __DIR__;
out('root=' . $root);

/* find tt_data the same way svc_lib does, then the library beside it */
$data = null;
foreach ([dirname($root) . '/tt_data', dirname($root, 2) . '/tt_data', '/home/u732570899/tt_data'] as $c) {
  if (is_dir($c)) { $data = $c; break; }
}
if (!$data) { out('could not find tt_data'); exit; }
$lib = dirname($data) . '/tt_library/3_Docs_Playbooks';
if (!is_dir($lib)) { if (!@mkdir($lib, 0755, true)) { out('could not make ' . $lib); exit; } out('made ' . $lib); }

$body = base64_decode('');
if ($body === false || strlen($body) < 500) { out('payload unreadable'); exit; }
$name = 'Command-Center-Operations-' . date('Y-m-d') . '.md';
$f = $lib . '/' . $name;
if (@file_put_contents($f, $body) === false) { out('could not write ' . $name); exit; }
out('wrote ' . $name . ' (' . strlen($body) . ' bytes)');
out('into ' . $lib);
/* clear out an older copy of the same manual so the Library does not collect duplicates */
foreach (glob($lib . '/Command-Center-Operations-*.md') ?: [] as $old) {
  if (basename($old) !== $name) { @unlink($old); out('replaced older copy: ' . basename($old)); }
}
out('--- DONE. Open the Command Center > Library > Docs & playbooks ---');
